begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create temporary table source_test_ids(name text primary key,id bigint);
insert into source_test_ids values('a',public.manage_directory_source('add',null,'https://jobs-a.example.org/rss','Board A')),('b',public.manage_directory_source('add',null,'https://jobs-b.example.org/atom','Board B'));
create function pg_temp.item(key text,url text,organisation text default 'Example Nature Trust',place text default 'Exeter, Devon',title text default 'Ecologist') returns jsonb language sql as $$
 select jsonb_build_object('feed_id',key,'slug',key,'source_url',url,'canonical_url',url,'title',title,'organisation_name',organisation,'feed_text','Survey woodland and advise landowners.','feed_hash','hash-'||key,'summary','Survey woodland.','summary_source','source','location_text',place,'locality',split_part(place,',',1),'country_code','GB','salary_text','£30,000 per year','salary_min',30000,'workplace','On-site','hours_type','Full time','contract_type','Permanent','posted_at',now(),'is_active',true)
$$;
select is((select count(*) from public.directory_sources where removed_at is null and id in(select id from source_test_ids)),2::bigint,'Sources can be added independently');
select is((select next_feed_at<=now() from public.directory_settings),true,'Adding a source wakes the existing automation');
select public.import_directory_feed((select id from source_test_ids where name='a'),'https://jobs-a.example.org/rss',jsonb_build_array(pg_temp.item('a1','https://jobs-a.example.org/role/1')));
insert into source_test_ids select 'card',job_id from public.directory_source_jobs where source_id=(select id from source_test_ids where name='a') and external_id='a1';
select public.import_directory_feed((select id from source_test_ids where name='b'),'https://jobs-b.example.org/atom',jsonb_build_array(pg_temp.item('a1','https://jobs-b.example.org/role/99','Example Nature Trust Ltd','Exeter, GB')));
select is((select count(distinct job_id) from public.directory_source_jobs where source_id in(select id from source_test_ids where name in('a','b'))),1::bigint,'Cross-source employer/title/city matches share one stable card');
select is((select count(*) from public.directory_source_jobs where source_id in(select id from source_test_ids where name in('a','b'))),2::bigint,'The same GUID in different feeds keeps both listings');
select public.apply_directory_job((select id from source_test_ids where name='card'),'hash-a1',jsonb_build_object('summary','An original AI summary.','sector_slugs',jsonb_build_array('ecology'),'course_slugs',jsonb_build_array('project-management-for-wildlife-conservation')),true);
select is((select processed_hash=feed_hash from public.directory_jobs where id=(select id from source_test_ids where name='card')),true,'One canonical card is enriched once');
select public.import_directory_feed((select id from source_test_ids where name='b'),'https://jobs-b.example.org/atom',jsonb_build_array(pg_temp.item('a1','https://jobs-b.example.org/role/99','Example Nature Trust Ltd','Exeter, GB')));
select is((select summary from public.directory_jobs where id=(select id from source_test_ids where name='card')),'An original AI summary.','An unchanged duplicate snapshot preserves the existing summary');
select is((select processed_hash=feed_hash from public.directory_jobs where id=(select id from source_test_ids where name='card')),true,'Unchanged duplicate snapshots do not repeat AI work');
-- Failed fetches never call import_directory_feed. Existing source snapshots remain intact.
update public.directory_sources set last_error='Feed HTTP 503' where id=(select id from source_test_ids where name='a');
select is((select is_active from public.directory_jobs where id=(select id from source_test_ids where name='card')),true,'A source fetch failure does not withdraw its existing cards');
select public.import_directory_feed((select id from source_test_ids where name='a'),'https://jobs-a.example.org/rss','[]');
select is((select is_active from public.directory_jobs where id=(select id from source_test_ids where name='card')),true,'Disappearing from one feed does not retire a job present in another');
select is((select source_name from public.directory_jobs where id=(select id from source_test_ids where name='card')),'Board B','The card switches to the remaining source');
select is((select source_url from public.directory_jobs where id=(select id from source_test_ids where name='card')),'https://jobs-b.example.org/role/99','The advert link follows the remaining source');
select public.manage_directory_source('pause',(select id from source_test_ids where name='b'));
select is((select is_active from public.directory_jobs where id=(select id from source_test_ids where name='card')),true,'Pausing imports keeps existing cards available');
select public.manage_directory_source('remove',(select id from source_test_ids where name='b'));
select is((select is_active from public.directory_jobs where id=(select id from source_test_ids where name='card')),false,'Removing the last source withdraws the card');
select public.manage_directory_source('add',null,'https://jobs-b.example.org/atom','Board B restored');
select public.import_directory_feed((select id from source_test_ids where name='b'),'https://jobs-b.example.org/atom',jsonb_build_array(pg_temp.item('a1','https://jobs-b.example.org/role/99','Example Nature Trust Ltd','Exeter, GB'),pg_temp.item('b2','https://jobs-b.example.org/role/2','Example Nature Trust','Bristol')));
select is((select count(distinct job_id) from public.directory_source_jobs where source_id=(select id from source_test_ids where name='b') and is_present),2::bigint,'Matching roles in different cities stay separate');
-- Metadata/AI can identify an initially unstructured duplicate after ingestion.
select public.import_directory_feed((select id from source_test_ids where name='a'),'https://jobs-a.example.org/rss',jsonb_build_array(pg_temp.item('a3','https://jobs-a.example.org/role/3','Organisation not stated','Location not stated','Reserve Ranger')));
select public.import_directory_feed((select id from source_test_ids where name='b'),'https://jobs-b.example.org/atom',jsonb_build_array(pg_temp.item('b3','https://jobs-b.example.org/role/3','Example Woodland Trust','Bath','Reserve Ranger')));
insert into source_test_ids select 'unstructured',job_id from public.directory_source_jobs where source_id=(select id from source_test_ids where name='a') and external_id='a3';
insert into source_test_ids select 'structured',job_id from public.directory_source_jobs where source_id=(select id from source_test_ids where name='b') and external_id='b3';
insert into auth.users(id,email) values('30000000-0000-0000-0000-000000000001','source-save@example.test');
insert into public.candidate_profiles(user_id) values('30000000-0000-0000-0000-000000000001');
insert into public.directory_saved_jobs(user_id,job_id) select '30000000-0000-0000-0000-000000000001',id from source_test_ids where name='structured';
select public.apply_directory_job((select id from source_test_ids where name='unstructured'),'hash-a3',jsonb_build_object('organisation_name','Example Woodland Trust','location_text','Bath','locality','Bath','summary','A concise ranger summary.','sector_slugs',jsonb_build_array('conservation-wildlife'),'course_slugs',jsonb_build_array()),true);
select is((select count(distinct job_id) from public.directory_source_jobs where external_id in('a3','b3') and source_id in(select id from source_test_ids where name in('a','b'))),1::bigint,'Learning employer and location merges an unstructured duplicate automatically');
select is((select job_id from public.directory_saved_jobs where user_id='30000000-0000-0000-0000-000000000001'),(select least(a.id,b.id) from source_test_ids a,source_test_ids b where a.name='unstructured' and b.name='structured'),'Bookmarks follow the canonical card through a merge');
select is((select count(*) from public.directory_jobs where id in(select id from source_test_ids where name in('structured','unstructured')) and is_active),1::bigint,'Only one duplicate card is public after enrichment');
select public.import_directory_feed((select id from source_test_ids where name='a'),'https://jobs-a.example.org/rss',jsonb_build_array(pg_temp.item('a3','https://jobs-a.example.org/role/3','Organisation not stated','Location not stated','Reserve Ranger')));
select is((select summary from public.directory_jobs where id=(select id from source_test_ids where name='unstructured')),'A concise ranger summary.','An unchanged unstructured feed does not erase learned identity or AI summary');
set local role anon;
select throws_ok($$select * from public.directory_sources$$,'42501',null,'Source management is not public');
select throws_ok($$select * from public.directory_source_jobs$$,'42501',null,'Raw source snapshots are not public');
select throws_ok($$select public.manage_directory_source('add',null,'https://malicious.example.org/rss','Untrusted')$$,'42501',null,'Anonymous clients cannot add sources');
select throws_ok($$select public.import_directory_feed(1,'https://example.org/rss','[]')$$,'42501',null,'Anonymous clients cannot replace source snapshots');
select throws_ok($$select public.apply_directory_job(1,'hash','{}',true)$$,'42501',null,'Anonymous clients cannot overwrite canonical jobs');
reset role;
select * from finish();
rollback;
